    bb_detener: "⏹ Detener",
    bb_nave_modo: "🚀 <b>Modo nave</b> — <kbd>↑↓←→</kbd> mover · mouse (clic y arrastra) mirar",
    bb_nave_lento: "Vuelo lento",
