    // ── METODOLOGÍA ──
    met_ayuda_hint: "💡 <b>Click any underlined term</b> to see its full definition. Terms in <span class=\"glos\">green</span> open a detailed explanation.",
    met_index_title: "Sections on this page:",
    met_marco_h2: "📐 Scientific framework: positional astronomy, not predictive astrology",
    met_marco_subtitle: "This note is addressed to researchers trained in the natural sciences who find astrological language uncomfortable. The clarification is important for the project's communicative integrity.",
    met_que_calc_h3: "What exactly do we calculate?",
