    // ── TABLERO ──
    tablero_h2: "Résultats du modèle nul",
    tablero_p: "Résultats précalculés par <code>nullmodel.py</code>. Choisissez le <b>domaine</b> pour comparer séismes, ouragans, etc.",
    tablero_domain_label: "Domaine à analyser",
    tablero_csv_btn: "Charger un autre CSV",
    tablero_volcano_h2: "Volcano plot — effet vs. significativité",
    tablero_volcano_hint: "Chaque point est une configuration astrologique. <b>Axe X</b> : taille de l'effet (log₂ du risque relatif ; droite = excès par rapport au hasard, gauche = déficit). <b>Axe Y</b> : significativité (−log₁₀ p). Le <span class=\"sig\">vert</span> survit à la correction pour comparaisons multiples (FDR&lt;0,05) : c'est là qu'est la science.",
    tablero_filter_all: "Tous les traits",
    tablero_filter_aspect: "Aspects seulement",
