    // ── METODOLOGÍA ──
    met_ayuda_hint: "💡 <b>Cliquez sur n'importe quel terme souligné</b> pour voir sa définition complète. Les termes en <span class=\"glos\">vert</span> ouvrent une explication détaillée.",
    met_index_title: "Sections de cette page :",
    met_marco_h2: "📐 Cadre scientifique : astronomie de position, pas astrologie prédictive",
    met_marco_subtitle: "Cette note s'adresse aux chercheurs formés aux sciences naturelles que le langage astrologique met mal à l'aise. Cette clarification est importante pour l'intégrité communicative du projet.",
    met_que_calc_h3: "Que calculons-nous exactement ?",
